SELECT COUNT(DISTINCT rc."REC_COMP") FROM reg_compliance rc 
JOIN market_conditions mc ON rc."REC_COMP" = mc."REC_PIN"
WHERE EXISTS (SELECT 1 FROM trade_records tr WHERE tr."REC_KEY" = rc."REC_COMP" AND tr.snap_ts IS NOT NULL AND tr.snap_ts != 'None');
